    {id:"period",name:"Period from frequency",symbol:"T = 1 / f",method:"UT",subject:"Wave & acoustics",difficulty:"Beginner",keywords:"period frequency cycles time",explain:"The period is the time for one cycle. It is the reciprocal of frequency.",vars:[["T","Period","s"],["f","Frequency","Hz"]],assumptions:"Use frequency in hertz for the SI result.",example:"At 2 MHz, T = 1 / 2,000,000 = 0.5 μs.",mistakes:"Using MHz as if it were Hz when calculating seconds.",inputs:[["f","Frequency (MHz)",2]],compute:x=>({value:1/x.f,unit:"µs",explain:"With frequency entered in MHz, the reciprocal is numerically the period in microseconds."}),lesson:"UT Fundamentals · Frequency and period"},
    {id:"speed-conversion",name:"Ultrasonic velocity unit conversion",symbol:"1 mm/µs = 1000 m/s",method:"UT",subject:"SI conversions",difficulty:"Beginner",keywords:"unit conversion speed mm microsecond metre second velocity",explain:"UT settings often display velocity in mm/μs, while SI velocity is commonly expressed in m/s. One mm per microsecond equals 1000 m/s.",vars:[["v","Velocity","mm/µs or m/s"],["vSI","Converted velocity","m/s"]],assumptions:"This conversion applies to speed units only; do not confuse it with time or distance conversion.",example:"5.92 mm/μs × 1000 = 5,920 m/s.",mistakes:"Multiplying or dividing by 1000 in the wrong direction.",inputs:[["v","Velocity (mm/µs)",5.92]],compute:x=>({value:x.v*1000,unit:"m/s",explain:"Multiply the numeric value in mm/µs by 1000 to express it in m/s."}),lesson:"Mathematics Fundamentals · SI unit conversions"},
    {id:"mm-to-m",name:"Millimetres to metres",symbol:"m = mm / 1000",method:"General / UT",subject:"SI conversions",difficulty:"Beginner",keywords:"SI units conversion length mm metre",explain:"A metre contains 1000 millimetres. Convert length to SI metres before combining it with velocity in m/s.",vars:[["xmm","Length","mm"],["xm","Length","m"]],assumptions:"This is a length conversion; area and volume require squared or cubed conversion factors.",example:"42.5 mm = 42.5 / 1000 = 0.0425 m.",mistakes:"Using the length conversion factor for area or volume.",inputs:[["mm","Length (mm)",42.5]],compute:x=>({value:x.mm/1000,unit:"m",explain:"Divide millimetres by 1000 to obtain metres."}),lesson:"Mathematics Fundamentals · SI unit conversions"},
    {id:"pythagorean",name:"Pythagorean theorem",symbol:"c = √(a² + b²)",method:"General / UT",subject:"Math & geometry",difficulty:"Beginner",keywords:"right triangle hypotenuse geometry sound path",explain:"For a right-angled triangle, the hypotenuse is the square root of the sum of the squares of the two perpendicular sides. It is useful for basic path-geometry exercises.",vars:[["c","Hypotenuse","same length unit as a and b"],["a","Perpendicular side a","mm or m"],["b","Perpendicular side b","mm or m"]],assumptions:"The angle between a and b is exactly 90° and both lengths use the same unit.",example:"If a = 30 mm and b = 40 mm, c = √(900 + 1600) = 50 mm.",mistakes:"Using the formula for a triangle that is not right-angled or mixing units.",inputs:[["a","Side a (mm)",30],["b","Side b (mm)",40]],compute:x=>({value:Math.sqrt(x.a*x.a+x.b*x.b),unit:"mm",explain:"The result uses the same length unit as both input sides."}),lesson:"Mathematics Fundamentals · Trigonometry and geometry"},
    {id:"rectangle-area",name:"Rectangle area",symbol:"A = L × W",method:"General / UT",subject:"Math & geometry",difficulty:"Beginner",keywords:"area length width rectangle scan area",explain:"The area of a rectangle is its length multiplied by its width. It is a basic geometry calculation for component or scan-area planning.",vars:[["A","Area","mm² or m²"],["L","Length","same unit as width"],["W","Width","same unit as length"]],assumptions:"Both dimensions use the same length unit.",example:"A 120 mm × 80 mm area is 9,600 mm².",mistakes:"Reporting area with a linear unit or mixing millimetres and metres.",inputs:[["L","Length (mm)",120],["W","Width (mm)",80]],compute:x=>({value:x.L*x.W,unit:"mm²",explain:"Area uses the square of the input length unit."}),lesson:"Mathematics Fundamentals · Geometry"},
    {id:"cylinder-volume",name:"Cylinder volume",symbol:"V = π r² L",method:"General / UT",subject:"Math & geometry",difficulty:"Beginner",keywords:"volume cylinder radius length specimen geometry",explain:"The volume of a right circular cylinder equals the circular cross-sectional area multiplied by its length.",vars:[["V","Volume","mm³ or cm³"],["r","Radius","mm"],["L","Cylinder length","mm"]],assumptions:"The object is a right circular cylinder and the radius is not the diameter.",example:"For r = 10 mm and L = 50 mm, V = π × 10² × 50 ≈ 15,708 mm³ = 15.71 cm³.",mistakes:"Using diameter instead of radius or forgetting the cubic unit.",inputs:[["r","Radius (mm)",10],["L","Length (mm)",50]],compute:x=>({value:Math.PI*x.r*x.r*x.L/1000,unit:"cm³",explain:"The input volume is mm³ and is divided by 1000 to express cm³."}),lesson:"Mathematics Fundamentals · Geometry"},
    {id:"db-from-amplitude",name:"Decibel difference from amplitude ratio",symbol:"ΔdB = 20 log₁₀(A₂ / A₁)",method:"UT / PAUT / TOFD",subject:"Gain & amplitude",difficulty:"Intermediate",keywords:"decibel logarithm amplitude ratio gain reference signal",explain:"This equation calculates the decibel difference between two comparable amplitude measurements.",vars:[["ΔdB","Level difference","dB"],["A₂","Compared amplitude","same units as A₁"],["A₁","Reference amplitude","same units as A₂"]],assumptions:"Both amplitudes must be positive and measured under comparable conditions. This is not the power/intensity formula.",example:"A₂/A₁ = 2 gives ΔdB = 20 log₁₀(2) ≈ 6.02 dB.",mistakes:"Taking the logarithm of zero or a negative value, or using 10 log for amplitude ratio.",inputs:[["a2","Compared amplitude A₂",2],["a1","Reference amplitude A₁",1]],compute:x=>(x.a1<=0||x.a2<=0)?{error:"Both amplitudes must be greater than zero."}:{value:20*Math.log10(x.a2/x.a1),unit:"dB",explain:"Positive values indicate a higher compared amplitude; negative values indicate a lower amplitude."},lesson:"Calibration · Gain and dB calculations"},
    {id:"db-power",name:"Power or intensity ratio from decibels",symbol:"P₂ / P₁ = 10^(ΔdB / 10)",method:"UT",subject:"Gain & amplitude",difficulty:"Intermediate",keywords:"power intensity ratio decibel logarithm",explain:"For power or intensity quantities, a decibel difference uses 10 times the base-10 logarithm of the ratio.",vars:[["P₂/P₁","Power or intensity ratio","dimensionless"],["ΔdB","Level difference","dB"]],assumptions:"Use this relation for power/intensity ratios, not for pressure or voltage-like amplitude ratios.",example:"A 10 dB increase corresponds to a power/intensity ratio of 10.",mistakes:"Confusing the 10 log power relationship with the 20 log amplitude relationship.",inputs:[["db","Level difference (dB)",10]],compute:x=>({value:Math.pow(10,x.db/10),unit:"× power/intensity ratio",explain:"A 10 dB difference corresponds to a factor of ten in power or intensity."}),lesson:"Calibration · Decibel relationships"}
