    {id:"frequency-units",name:"Frequency: MHz to Hz",symbol:"f(Hz) = f(MHz) × 10⁶",method:"General / UT",subject:"SI conversions",difficulty:"Beginner",keywords:"frequency hertz megahertz SI unit conversion",explain:"One megahertz is one million hertz. Convert the frequency before combining it with velocity in metres per second.",vars:[["fHz","Frequency","Hz"],["fMHz","Frequency","MHz"]],assumptions:"Input is a numeric value expressed in MHz.",example:"2.25 MHz = 2.25 × 1,000,000 = 2,250,000 Hz.",mistakes:"Using MHz directly in an equation that expects Hz.",inputs:[["f","Frequency (MHz)",2.25]],compute:x=>({value:x.f*1e6,unit:"Hz",explain:"Multiply MHz by one million to obtain Hz."}),lesson:"UT Fundamentals · Frequency and wavelength"},
    {id:"ratio-proportion",name:"Ratio and proportion",symbol:"x = (a × b) / c",method:"General / UT",subject:"Math & geometry",difficulty:"Beginner",keywords:"ratio proportion rearrange algebra scale",explain:"If x/a = b/c, rearrange by multiplying both sides to obtain x = ab/c. This is a simple example of rearranging an equation.",vars:[["x","Unknown value","same units as the resulting quantity"],["a","Known value","unit depends on problem"],["b","Known value","unit depends on problem"],["c","Known nonzero value","unit depends on problem"]],assumptions:"The denominator c must be nonzero and the ratio units must be compatible.",example:"If x/10 = 6/3, then x = 10 × 6 / 3 = 20.",mistakes:"Dividing by zero or mixing quantities with incompatible units.",inputs:[["a","Value a",10],["b","Value b",6],["c","Value c",3]],compute:x=>x.c===0?{error:"The denominator c cannot be zero."}:{value:x.a*x.b/x.c,unit:"calculated units",explain:"Check that the input units make the resulting ratio physically meaningful."},lesson:"Mathematics Fundamentals · Algebra and proportions"},
    {id:"scientific-notation",name:"Scientific notation",symbol:"x = a × 10ⁿ",method:"General / UT",subject:"Math & geometry",difficulty:"Beginner",keywords:"scientific notation powers of ten exponential large small numbers",explain:"Scientific notation expresses a number as a coefficient multiplied by a power of ten. It helps manage very small wavelengths and short travel times.",vars:[["x","Number","unit of the original quantity"],["a","Coefficient","dimensionless"],["n","Integer exponent","dimensionless"]],assumptions:"The coefficient is commonly written with 1 ≤ |a| < 10 for normalized scientific notation.",example:"0.000001 s = 1 × 10⁻⁶ s = 1 μs.",mistakes:"Moving the decimal point in the wrong direction or losing the sign of the exponent.",inputs:[["a","Coefficient",1.25],["n","Exponent n",-6]],compute:x=>({value:x.a*Math.pow(10,Math.trunc(x.n)),unit:"× 10^"+Math.trunc(x.n),explain:"The displayed value is the numeric coefficient multiplied by the entered power of ten."}),lesson:"Mathematics Fundamentals · Scientific notation"}
